files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: #1a1a2e;
  color: #e0e0e0;
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: #16213e;
  border: 4px solid #0f3460;
  border-radius: 0;
  box-shadow: 8px 8px 0 #0f3460;
  padding: 32px 24px;
  max-width: 400px;
  width: 100%;
  text-align: center;
}

h1 {
  font-size: 28px;
  margin-bottom: 24px;
  color: #e94560;
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 #0f3460;
}

#question {
  font-size: 24px;
  margin-bottom: 24px;
  padding: 16px;
  background: #0f3460;
  border: 2px solid #533483;
  color: #e0e0e0;
  word-break: break-word;
}

.answers {
  display: flex;
  gap: 16px;
  margin-bottom: 24px;
}

button {
  font-family: inherit;
  font-size: 20px;
  padding: 12px 24px;
  border: 3px solid #533483;
  background: #1a1a2e;
  color: #e0e0e0;
  cursor: pointer;
  transition: none;
  flex: 1;
  min-width: 0;
  text-transform: uppercase;
  letter-spacing: 1px;
}

button:hover {
  background: #533483;
  border-color: #e94560;
}

button:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

button:active {
  background: #e94560;
  border-color: #e94560;
  transform: translate(2px, 2px);
  box-shadow: none;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  background: #1a1a2e;
  border-color: #533483;
  transform: none;
}

#score {
  font-size: 22px;
  color: #e94560;
  font-weight: bold;
}

p {
  margin-bottom: 24px;
  font-size: 18px;
}

.controls {
  display: flex;
  gap: 16px;
}

@media (max-width: 360px) {
  .card {
    padding: 24px 16px;
  }
  button {
    padding: 10px 16px;
    font-size: 18px;
  }
  #question {
    font-size: 20px;
  }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

let score = 0;
let currentQuestion = 1;
let answered = false;

function updateDisplay() {
  scoreEl.textContent = score;
}

function lockAnswers() {
  answerA.disabled = true;
  answerB.disabled = true;
  answered = true;
}

function unlockAnswers() {
  answerA.disabled = false;
  answerB.disabled = false;
  answered = false;
}

function handleAnswer(isCorrect) {
  if (answered) return;
  lockAnswers();
  if (isCorrect) {
    score += 1;
    updateDisplay();
  }
}

answerA.addEventListener('click', () => {
  if (currentQuestion === 1) {
    handleAnswer(true);
  } else if (currentQuestion === 2) {
    handleAnswer(false);
  }
});

answerB.addEventListener('click', () => {
  if (currentQuestion === 1) {
    handleAnswer(false);
  } else if (currentQuestion === 2) {
    handleAnswer(true);
  }
});

nextBtn.addEventListener('click', () => {
  if (currentQuestion === 1) {
    currentQuestion = 2;
    questionEl.textContent = '3 + 3 = ?';
    answerA.textContent = '5';
    answerB.textContent = '6';
    unlockAnswers();
  } else if (currentQuestion === 2) {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
  }
});

restartBtn.addEventListener('click', () => {
  score = 0;
  currentQuestion = 1;
  answered = false;
  questionEl.textContent = '2 + 2 = ?';
  answerA.textContent = '4';
  answerB.textContent = '5';
  unlockAnswers();
  nextBtn.disabled = false;
  updateDisplay();
});

updateDisplay();
